We model the channel vector ${\bf h}_{k,n}$ by using the virtual angular domain
 representation \cite{{TSE},{Virtual_rep}}
 \begin{equation} y_n = {\bf h}_n^{\rm T} {\bf x}_n + w_n = \widetilde{\bf h}_n^{\rm T}{\bf A}_B^{*}
  {\bf x}_n + w_n ,
\end{equation}
 where the user index $k$ in $y_{k,n}$, ${\bf h}_{k,n}$ and $w_{k,n}$ is dropped to
 simplify the notations, while ${\bf h}_n^{\rm T} =\widetilde{\bf h}_n^{\rm T}{\bf A}_B^{*}$
 and ${\bf A}_B\in \mathbb{C}^{M\times M}$ is the unitary matrix representing the
 transformation matrix of the virtual angular domain at the BS side.

Consequently, $\left\{\widetilde{\bf h}_n\right\}_{n=1}^{N}$
 have the common sparsity, namely,
 \begin{equation} {\rm supp}\left\{\widetilde{\bf h}_1\right\} = {\rm supp}\left\{\widetilde{\bf h}_2\right\}
 = \cdots = {\rm supp}\left\{\widetilde{\bf h}_N\right\} = \Theta ,
\end{equation}
 which is illustrated in Fig.~\ref{fig:CSI_matrix}.

This implies that
\begin{equation} {\rm supp}\!\left\{ \widetilde{\bf h}_n^{(q)}\!\right\} ={\rm supp}\!\left\{ \widetilde{\bf h}_n^{(q+1)}\!\right\}
 \!\!   =  \!\cdots \!= {\rm supp}\!\left\{ \widetilde{\bf h}_n^{(q+Q-1)}\!\right\} ,
\end{equation}
 where $Q$ is the number of consecutive time blocks over the duration of which the
 common support of virtual angular domain channels holds.

Due to the quasi-static property of the channel during one time block, the feedback signals
 in $G$ successive time slots can be jointly exploited to acquire the downlink CSI
 at the BS, which can be expressed as
\begin{align} \!\! {\bf r}_p^{[q,G]} \! =\! {\bf S}_p^{[q,G]} \big( {\bf A}_B^{*} \big)^{\rm T} \bar{\bf h}_p^{(q)}
\!  + \!{\bf v}_p^{[q,G]}\! = \!{\bf \Phi}_p^{[q,G]} \bar{\bf h}_p^{(q)} \!+ \!{\bf v}_p^{[q,G]} ,
\end{align}
 for $1\le p \le P$, where ${\bf r}_p^{[q,G]}=\big[ r_p^{(q,1)} ~ r_p^{(q,2)} \cdots
 r_p^{(q,G)}\big]^{\rm T}$, ${\bf S}_p^{[q,G]}=\big[ {\bf s}_p^{(q,1)} ~ {\bf s}_p^{(q,2)}
 \cdots {\bf s}_p^{(q,G)}\big]^{\rm T}\in \mathbb{C}^{G\times M}$, ${\bf v}_p^{[q,G]}=
 \big[ v_p^{(q,1)} ~ v_p^{(q,2)} ~ \cdots v_p^{(q,G)}\big]^{\rm T}$ and ${\bf \Phi}_p^{[q,G]}
 ={\bf S}_p^{[q,G]} \big( {\bf A}_B^{*} \big)^{\rm T}\in \mathbb{C}^{G\times M}$.

\caption{CS Based Adaptive CSI Acquisition Scheme} \begin{algorithmic}[1]
\STATE Determine the initial time slot overhead $G_0$, and set the iteration index $i=0$.
\REPEAT
\STATE Collect ${\bf r}_p^{[q,G_i]}$ and ${\bf \Phi}_p^{[q,G_i]}$ in (\ref{equ:joint_process2})
 for given $G_i$, $1\le p \le P$. {\scriptsize \%~$G_i$ is the required overhead at the
 $i$th iteration.}
\STATE Acquire the channel vectors $\widehat{\bar{\bf h}}_p^{(q)}$ $\forall p$ by using
 the proposed DSAMP algorithm (Algorithm~\ref{alg:Framwork}).
\STATE $G_{i+1} = G_i + 1$; $i = i+1$.
\UNTIL {$\sum\limits_{p=1}^{P}\!\left\| {\bf r}_p^{[q,G_{i-1}]}\!-\!{\bf \Phi}_p^{[q,G_{i-1}]}\widehat{\bar{\bf h}}_p^{(q)}
 \!\right\|_2^2\!\!/\!({P}G_{i-1})\!\!\le\! \varepsilon$}. {\scriptsize \%~If the error is smaller than the
 threshold $\varepsilon$, end repeat; otherwise, continue transmitting the pilot in the next time~slot.}
\STATE $G_0=G_i-1$. ${\kern 5pt}$ {\scriptsize \%~Optional, determine the initial time slot
 overhead for the next CS based adaptive CSI acquisition.}
\end{algorithmic}

